import React, { useEffect, useState } from 'react';

const ProductDetail = () => {
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const productId = '67a76f200449b2837c6835ae'; // Örnek bir MongoDB ObjectId'si
    fetch(`http://localhost:3001/api/products/${productId}`)
      .then((response) => response.json())
      .then((data) => {
        setProduct(data); // Veriyi state'e kaydet
        console.log(data._id); // _id'yi konsola yazdır
        setLoading(false); // Veriyi aldıktan sonra loading'i false yap
      })
      .catch((error) => {
        console.error('Hata oluştu:', error);
        setLoading(false);
      });
  }, []); // Bu effect sadece component mount olduğunda çalışacak

  // Yükleniyorsa loading mesajını göster
  if (loading) {
    return <div>Yükleniyor...</div>;
  }

  // Ürün verisi geldiğinde ekranda göster
  return (
    <div>
      <h1>{product.name}</h1>
      <p>{product.category}</p>
      <p>{product.price} TL</p>
      <p>{product.productdetails}</p>
      {/* Ürün fotoğrafı burada gösterilebilir */}
      <img src={product.photo} alt={product.name} />
    </div>
  );
};

export default ProductDetail;
